-- 0001_initial_schema: local node state for Skep 0.1.0.
--
-- Conventions
--   * IDs are opaque text (UUIDs) generated by Skep and never reused.
--   * Timestamps are UTC ISO 8601 text, e.g. 2026-11-11T12:00:00.000Z.
--   * Desired state and observed state never share a column. Columns named
--     desired_* hold what an administrator asked for; columns named
--     observed_* hold what the agent last saw on the host, and observed_at
--     says when. Configuration columns (cpu_count, size_bytes, ...) are part
--     of desired state. History lives in task_events and audit_log.
--   * JSON documents are stored as text and validated with json_valid().
--   * No column holds a plaintext secret. users.password_hash is an Argon2id
--     hash; system_config must not be used for secrets.
--   * This database is local node state, not the cluster database.

CREATE TABLE system_config (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE nodes (
    id                  TEXT PRIMARY KEY,
    name                TEXT NOT NULL UNIQUE,
    is_local            INTEGER NOT NULL DEFAULT 0 CHECK (is_local IN (0, 1)),
    -- desired
    desired_state       TEXT NOT NULL DEFAULT 'active'
                        CHECK (desired_state IN ('active', 'maintenance')),
    -- observed. A node that cannot be reached is 'unreachable', never "dead".
    observed_state      TEXT NOT NULL DEFAULT 'unknown'
                        CHECK (observed_state IN ('unknown', 'online', 'unreachable')),
    observed_hostname   TEXT,
    observed_os_name    TEXT,
    observed_os_release TEXT,
    observed_arch       TEXT,
    observed_hardware   TEXT CHECK (observed_hardware IS NULL OR json_valid(observed_hardware)),
    observed_at         TEXT,
    created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- At most one node row describes the host this database belongs to.
CREATE UNIQUE INDEX nodes_single_local ON nodes (is_local) WHERE is_local = 1;

CREATE TABLE storage_pools (
    id                       TEXT PRIMARY KEY,
    node_id                  TEXT NOT NULL REFERENCES nodes (id) ON DELETE RESTRICT,
    name                     TEXT NOT NULL,
    type                     TEXT NOT NULL CHECK (type IN ('zfs', 'directory')),
    -- desired
    desired_enabled          INTEGER NOT NULL DEFAULT 1 CHECK (desired_enabled IN (0, 1)),
    -- observed
    observed_health          TEXT,
    observed_size_bytes      INTEGER CHECK (observed_size_bytes IS NULL OR observed_size_bytes >= 0),
    observed_allocated_bytes INTEGER CHECK (observed_allocated_bytes IS NULL OR observed_allocated_bytes >= 0),
    observed_free_bytes      INTEGER CHECK (observed_free_bytes IS NULL OR observed_free_bytes >= 0),
    observed_at              TEXT,
    created_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (node_id, name)
) STRICT;

CREATE TABLE storage_volumes (
    id                  TEXT PRIMARY KEY,
    pool_id             TEXT NOT NULL REFERENCES storage_pools (id) ON DELETE RESTRICT,
    name                TEXT NOT NULL,
    -- Datasets hold files; zvols back VM block devices.
    kind                TEXT NOT NULL CHECK (kind IN ('dataset', 'zvol', 'file')),
    -- desired
    desired_size_bytes  INTEGER CHECK (desired_size_bytes IS NULL OR desired_size_bytes > 0),
    -- observed
    observed_exists     INTEGER CHECK (observed_exists IS NULL OR observed_exists IN (0, 1)),
    observed_used_bytes INTEGER CHECK (observed_used_bytes IS NULL OR observed_used_bytes >= 0),
    observed_at         TEXT,
    created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (pool_id, name)
) STRICT;

CREATE TABLE virtual_machines (
    id              TEXT PRIMARY KEY,
    node_id         TEXT NOT NULL REFERENCES nodes (id) ON DELETE RESTRICT,
    name            TEXT NOT NULL UNIQUE,
    description     TEXT NOT NULL DEFAULT '',
    engine          TEXT NOT NULL CHECK (engine IN ('bhyve', 'qemu')),
    -- desired (configuration)
    cpu_count       INTEGER NOT NULL CHECK (cpu_count > 0),
    memory_bytes    INTEGER NOT NULL CHECK (memory_bytes > 0),
    firmware        TEXT NOT NULL DEFAULT 'uefi' CHECK (firmware IN ('uefi', 'bios')),
    config          TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(config)),
    desired_state   TEXT NOT NULL DEFAULT 'stopped'
                    CHECK (desired_state IN ('stopped', 'running')),
    -- observed (runtime)
    observed_state  TEXT NOT NULL DEFAULT 'unknown'
                    CHECK (observed_state IN ('unknown', 'stopped', 'starting', 'running', 'stopping', 'failed')),
    observed_detail TEXT,
    observed_at     TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX virtual_machines_node ON virtual_machines (node_id);

CREATE TABLE vm_disks (
    id                TEXT PRIMARY KEY,
    vm_id             TEXT NOT NULL REFERENCES virtual_machines (id) ON DELETE CASCADE,
    storage_volume_id TEXT REFERENCES storage_volumes (id) ON DELETE RESTRICT,
    slot              INTEGER NOT NULL CHECK (slot >= 0),
    bus               TEXT NOT NULL CHECK (bus IN ('virtio-blk', 'nvme', 'ahci-hd', 'ahci-cd')),
    size_bytes        INTEGER CHECK (size_bytes IS NULL OR size_bytes > 0),
    read_only         INTEGER NOT NULL DEFAULT 0 CHECK (read_only IN (0, 1)),
    boot_order        INTEGER,
    created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (vm_id, slot)
) STRICT;

CREATE INDEX vm_disks_volume ON vm_disks (storage_volume_id);

CREATE TABLE vm_networks (
    id          TEXT PRIMARY KEY,
    vm_id       TEXT NOT NULL REFERENCES virtual_machines (id) ON DELETE CASCADE,
    slot        INTEGER NOT NULL CHECK (slot >= 0),
    model       TEXT NOT NULL DEFAULT 'virtio-net' CHECK (model IN ('virtio-net', 'e1000')),
    mac_address TEXT UNIQUE,
    bridge      TEXT NOT NULL,
    vlan_tag    INTEGER CHECK (vlan_tag IS NULL OR vlan_tag BETWEEN 1 AND 4094),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (vm_id, slot)
) STRICT;

CREATE TABLE containers (
    id              TEXT PRIMARY KEY,
    node_id         TEXT NOT NULL REFERENCES nodes (id) ON DELETE RESTRICT,
    name            TEXT NOT NULL UNIQUE,
    kind            TEXT NOT NULL DEFAULT 'jail' CHECK (kind IN ('jail')),
    -- desired (configuration)
    hostname        TEXT NOT NULL DEFAULT '',
    root_volume_id  TEXT REFERENCES storage_volumes (id) ON DELETE RESTRICT,
    vnet            INTEGER NOT NULL DEFAULT 0 CHECK (vnet IN (0, 1)),
    config          TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(config)),
    desired_state   TEXT NOT NULL DEFAULT 'stopped'
                    CHECK (desired_state IN ('stopped', 'running')),
    -- observed (runtime)
    observed_state  TEXT NOT NULL DEFAULT 'unknown'
                    CHECK (observed_state IN ('unknown', 'stopped', 'starting', 'running', 'stopping', 'failed')),
    observed_jid    INTEGER,
    observed_detail TEXT,
    observed_at     TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX containers_node ON containers (node_id);

CREATE TABLE network_interfaces (
    id                  TEXT PRIMARY KEY,
    node_id             TEXT NOT NULL REFERENCES nodes (id) ON DELETE RESTRICT,
    name                TEXT NOT NULL,
    kind                TEXT NOT NULL
                        CHECK (kind IN ('physical', 'bridge', 'vlan', 'lagg', 'tap', 'epair', 'loopback', 'other')),
    -- desired. NULL means Skep observes the interface but does not manage it.
    desired_config      TEXT CHECK (desired_config IS NULL OR json_valid(desired_config)),
    -- observed
    observed_mac        TEXT,
    observed_mtu        INTEGER,
    observed_link_state TEXT CHECK (observed_link_state IS NULL OR observed_link_state IN ('up', 'down', 'unknown')),
    observed_addresses  TEXT CHECK (observed_addresses IS NULL OR json_valid(observed_addresses)),
    observed_at         TEXT,
    created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (node_id, name)
) STRICT;

CREATE TABLE roles (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    permissions TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(permissions)),
    built_in    INTEGER NOT NULL DEFAULT 0 CHECK (built_in IN (0, 1)),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE users (
    id            TEXT PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE,
    display_name  TEXT NOT NULL DEFAULT '',
    -- Argon2id hash in PHC string format. Never a plaintext password.
    password_hash TEXT NOT NULL CHECK (password_hash LIKE '$argon2id$%'),
    role_id       TEXT NOT NULL REFERENCES roles (id) ON DELETE RESTRICT,
    disabled      INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)),
    last_login_at TEXT,
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE tasks (
    id              TEXT PRIMARY KEY,
    node_id         TEXT REFERENCES nodes (id) ON DELETE RESTRICT,
    type            TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'running', 'succeeded', 'failed', 'cancelled', 'interrupted')),
    resource_type   TEXT,
    resource_id     TEXT,
    idempotency_key TEXT UNIQUE,
    requested_by    TEXT REFERENCES users (id) ON DELETE SET NULL,
    payload         TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload)),
    result          TEXT CHECK (result IS NULL OR json_valid(result)),
    error           TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    started_at      TEXT,
    finished_at     TEXT
) STRICT;

CREATE INDEX tasks_status ON tasks (status, created_at);
CREATE INDEX tasks_resource ON tasks (resource_type, resource_id);

CREATE TABLE task_events (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id    TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    level      TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('debug', 'info', 'warn', 'error')),
    message    TEXT NOT NULL,
    data       TEXT CHECK (data IS NULL OR json_valid(data)),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX task_events_task ON task_events (task_id, id);

-- The audit log is append-only. Actor columns are copies, not foreign keys,
-- so entries survive the deletion of the user they refer to.
CREATE TABLE audit_log (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    occurred_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    actor_id      TEXT,
    actor_name    TEXT NOT NULL,
    action        TEXT NOT NULL,
    resource_type TEXT,
    resource_id   TEXT,
    outcome       TEXT NOT NULL CHECK (outcome IN ('success', 'failure', 'denied')),
    source_ip     TEXT,
    request_id    TEXT,
    details       TEXT CHECK (details IS NULL OR json_valid(details))
) STRICT;

CREATE INDEX audit_log_occurred ON audit_log (occurred_at);
CREATE INDEX audit_log_resource ON audit_log (resource_type, resource_id);

CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only');
END;

CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only');
END;
